mapper.select:
SELECT instance_id FROM wf_process_instance
WHERE tenant_id = #{tenantId} AND process_no = #{processNo}
FOR UPDATE

SELECT * FROM wf_process_instance
WHERE tenant_id = #{tenantId} AND deleted = 0 AND instance_id > #{afterId}
  AND status IN ('RUNNING', 'RESTARTED', 'TASK_BACK', 'WITHDRAWN', 'PENDING', 'PAUSED', 'FAILED')
  AND JSON_CONTAINS_PATH(variables, 'one', '$._wf_waits') = 1
ORDER BY instance_id LIMIT #{limit}

SELECT i.instance_id AS instanceId, i.definition_id AS processDefId, i.process_def_key AS processDefKey, d.process_name AS processDefName, i.business_key AS businessKey, i.start_user_id AS startUserId, i.start_user_name AS startUserName, i.start_time AS startTime, i.end_time AS endTime, i.status AS status, ( SELECT t.node_name FROM wf_task t WHERE t.instance_id = i.instance_id AND t.status = 'TODO' ORDER BY t.create_time ASC LIMIT 1 ) AS currentNode FROM wf_process_instance i LEFT JOIN wf_process_definition d ON d.process_def_key = i.process_def_key WHERE i.instance_id IN
#{instanceId}
ORDER BY i.start_time DESC
